// MASTER TASK: System-type-aware panel default.
// Roof = Q CELLS 400W, Fence = Philadelphia Solar Nexus 440W (panel-fence-ps1),
// Ground = Q CELLS 400W (no dedicated default yet).
// Used by newString() and any other site that needs a seed panel ID.
function defaultPanelForSystemType(sysType?: string): string {
  if (sysType === 'fence') return 'panel-fence-ps1';
  return 'qcells-peak-duo-400';
}

// v47.357: The set of panel IDs that are recognized as "hardcoded defaults"
// (not real user choices). When we detect a fence project using one of these,
// we auto-correct to panel-fence-ps1. This preserves the non-destructive-defaults
// rule because we only swap when the current value was a default we ourselves planted.
const HARDCODED_DEFAULT_PANELS = new Set(['qcells-peak-duo-400']);

// v47.358: Set of inverter IDs that are recognized as hardcoded UI defaults
// (not real user choices). Used for fence→EcoFlow default promotion.
const HARDCODED_DEFAULT_INVERTERS = new Set<string>([
  'se-7600h',            // default for 'string' type
  'fronius-primo-8.2',   // common legacy default
]);

// Fence → EcoFlow default promotion (v47.358):
// If systemType is 'fence', topology is still 'string' (our default), AND the
// inverter is a hardcoded default (never a real user choice), promote the whole
// inverter to EcoFlow 'ecoflow-power-ocean-10kw' so SolFence projects automatically
// get EcoFlow PowerOcean as the baseline.
//
// This is a DEFAULT only — any explicit user inverter selection is preserved.
// Phase 11: kept as a library helper for future use / tests. No longer called
// from page.tsx runtime — silent promotion is prohibited.
// eslint-disable-next-line no-unused-vars
function reconcileFenceEcoFlowDefault(
  inverters: InverterConfig[],
  systemType: SystemType | undefined,
): InverterConfig[] {
  if (systemType !== 'fence') return inverters;
  let changed = false;
  const reconciled = inverters.map(inv => {
    // Only promote if:
    //  - current type is 'string' (our default topology), AND
    //  - inverterId is a hardcoded default (user never picked it explicitly)
    if (inv.type === 'string' && HARDCODED_DEFAULT_INVERTERS.has(inv.inverterId)) {
      // v61.13: dynamic lookup — never hardcode a potentially-inactive model.
      const _activeEF = STRING_INVERTERS.find(x => x.ecosystemBrand === 'ecoflow' && x.active !== false);
      const _ecoflowId = _activeEF?.id ?? 'ecoflow-ocean-pro-11kw';
      console.log(`[INVERTER RECONCILE] Fence project detected — promoting inverter ${inv.inverterId} → ${_ecoflowId}`);
      changed = true;
      return { ...inv, type: 'ecoflow' as InverterType, inverterId: _ecoflowId };
    }
    return inv;
  });
  return changed ? reconciled : inverters;
}

// Fence auto-correction: if systemType is fence but a string is still carrying
// a roof-default panel, swap to the fence default. Returns a new inverters array
// if any change was made, or the original reference if not.
// Phase 11: kept as a library helper. No longer called from page.tsx runtime.
// eslint-disable-next-line no-unused-vars
function reconcileFencePanels(
  inverters: InverterConfig[],
  systemType: SystemType | undefined,
): InverterConfig[] {
  if (systemType !== 'fence') return inverters;
  let changed = false;
  const reconciled = inverters.map(inv => {
    const newStrings = inv.strings.map(s => {
      if (HARDCODED_DEFAULT_PANELS.has(s.panelId)) {
        changed = true;
        console.log(`[PANEL RECONCILE] Fence project detected — swapping string "${s.label}" panel ${s.panelId} → panel-fence-ps1`);
        return { ...s, panelId: 'panel-fence-ps1' };
      }
      return s;
    });
    return changed ? { ...inv, strings: newStrings } : inv;
  });
  return changed ? reconciled : inverters;
}

// ── Wave 3.3 (contract §3 Wave 3 item 3 — sync-pipeline watcher scope) ──────
/**
 * Rebuild ONE sub's fleet to a new panel count using that fleet's OWN
 * equipment (its inverter model / panel / topology) — never a project-wide
 * winner or inverters[0]-of-the-project (I-3). Mirrors the legacy panel-count
 * fix branches (micro single-string update / sizing-engine regroup / capped
 * even-split fallback), but per fleet. Returns null when nothing sensible can
 * be built — the caller keeps the old fleet.
 */
function rebuildFleetForCount(
  fleet: InverterConfig[],
  key: SubSystemKey,
  targetCount: number,
  selectedBrand: string | undefined,
): InverterConfig[] | null {
  const inv0 = fleet[0];
  if (!inv0 || targetCount <= 0) return null;
  const baseStr = inv0.strings[0];

  // Micro: update the single string's total panel count — never N×1 strings.
  if (inv0.type === 'micro') {
    const newStr = _buildStrCfg({
      index:      0,
      existingId: baseStr?.id,
      panelCount: targetCount,
      panelId:    baseStr?.panelId,
      wireGauge:  baseStr?.wireGauge,
    });
    return [_buildInvCfg({
      existingId:   inv0.id,
      inverterId:   inv0.inverterId,
      type:         inv0.type,
      strings:      [newStr],
      subSystemKey: key,
    } as any)];
  }

  // String / optimizer / hybrid: this sub's own sizing pass.
  const panel = SOLAR_PANELS.find((pp: any) => pp.id === baseStr?.panelId) as any;
  let engStrings: Array<{ panelCount: number; inverterIndex?: number }> | null = null;
  try {
    const input: Parameters<typeof sizeSystemFromBrand>[0] = {
      systemType:        key,
      panelCount:        targetCount,
      panelWattage:      panel?.watts ?? 400,
      panelVoc:          panel?.voc ?? 49.6,
      panelTempCoeffVoc: panel?.tempCoeffVoc ?? -0.27,
      designTempMin:     -10,
      optimizerMaxOutputCurrent: 15.0,
    };
    if (inv0.inverterId)     input.selectedInverterId = inv0.inverterId;
    else if (selectedBrand)  input.selectedBrand      = selectedBrand;
    const result = sizeSystemFromBrand(input);
    if (result.strings.length > 0 && result.topology !== 'micro') engStrings = result.strings;
  } catch { /* fall through to even split */ }
  if (!engStrings) {
    const pps = Math.min(targetCount, 14);
    const sc  = Math.max(1, Math.ceil(targetCount / pps));
    engStrings = Array.from({ length: sc }, (_, i) => ({
      panelCount: i === sc - 1 ? targetCount - pps * (sc - 1) : pps,
      inverterIndex: 0,
    }));
  }
  const byInv = new Map<number, Array<{ panelCount: number }>>();
  for (const s of engStrings) {
    const idx = s.inverterIndex ?? 0;
    if (!byInv.has(idx)) byInv.set(idx, []);
    byInv.get(idx)!.push(s);
  }
  const invCount = Math.max(1, byInv.size);
  const out: InverterConfig[] = [];
  for (let idx = 0; idx < invCount; idx++) {
    const shell = fleet[idx] ?? inv0;
    const assigned = byInv.get(idx) ?? [];
    if (assigned.length === 0) { out.push(shell); continue; }
    const newStrings = assigned.map((s, si) => {
      const existing = shell.strings[si] ?? shell.strings[0];
      return _buildStrCfg({
        index:          si,
        panelCount:     s.panelCount,
        panelId:        existing?.panelId,
        existingId:     existing?.id ?? `str-sub-sync-${key}-${idx}-${si}`,
        label:          existing?.label,
        tilt:           existing?.tilt,
        azimuth:        existing?.azimuth,
        roofType:       existing?.roofType as any,
        mountingSystem: existing?.mountingSystem,
        wireGauge:      existing?.wireGauge,
        wireLength:     existing?.wireLength,
      });
    });
    out.push(_buildInvCfg({
      existingId:            shell.id,
      inverterId:            shell.inverterId,
      type:                  shell.type,
      strings:               newStrings,
      optimizerPeripheralId: (shell as any).optimizerPeripheralId,
      deviceRatioOverride:   (shell as any).deviceRatioOverride,
      subSystemKey:          key,
    } as any));
  }
  return out;
}

function newString(idx: number, sysType?: string): StringConfig {
  return { id: `str-${Date.now()}-${idx}`, label: `String ${idx + 1}`, panelCount: 10, panelId: defaultPanelForSystemType(sysType), tilt: 20, azimuth: 180, roofType: 'shingle', mountingSystem: 'ironridge-xr100', wireGauge: '#10 AWG', wireLength: 50 };
}

function newInverter(
  type: InverterType,
  sysType?: string,
  opts?: { subSystemKey?: SubSystemKey; panelCount?: number; panelId?: string },
): InverterConfig {
  // Use correct default inverterId per type — prevents cross-type ID mismatch.
  // v47.358: 'ecoflow' topology defaults to PowerOcean 10kW (middle tier).
  let defaultId: string;
  if (type === 'micro') {
    defaultId = MICROINVERTERS[0]?.id ?? 'enphase-iq8plus';
  } else if (type === 'ecoflow') {
    // v61.13: dynamic lookup — never hardcode a potentially-inactive model.
    const _activeEF = STRING_INVERTERS.find(x => x.ecosystemBrand === 'ecoflow' && x.active !== false);
    defaultId = _activeEF?.id ?? 'ecoflow-ocean-pro-11kw';
  } else {
    defaultId = STRING_INVERTERS[0]?.id ?? 'se-7600h';
  }
  // v61.3: route through central builder — guarantees metadata invariants.
  const base = newString(0, sysType);
  const firstString = (opts?.subSystemKey || opts?.panelCount !== undefined || opts?.panelId)
    ? _buildStrCfg({
        index:          0,
        systemType:     sysType,
        existingId:     base.id,
        panelCount:     opts?.panelCount ?? base.panelCount,
        panelId:        opts?.panelId ?? base.panelId,
        tilt:           base.tilt,
        azimuth:        base.azimuth,
        roofType:       base.roofType as any,
        mountingSystem: base.mountingSystem,
        wireGauge:      base.wireGauge,
        wireLength:     base.wireLength,
        subSystemKey:   opts?.subSystemKey,
      })
    : base;
  return _buildInvCfg({
    inverterId: defaultId,
    type,
    strings: [firstString],
    subSystemKey: opts?.subSystemKey,
  });
}

